parameters.jsCode:
// One Slack message per changed pricing page.
const quote = (lines) => lines.slice(0, 8).map((l) => `> ${l.slice(0, 200)}`).join('\n');
return $input.all().map(({ json: p }) => {
  const parts = [`:money_with_wings: *${p.name || p.title || p.url}* changed`, p.url];
  if (p.numericChanges && p.numericChanges.length) {
    parts.push('*Numbers:* ' + p.numericChanges.slice(0, 6).map((n) => `${n.before} → ${n.after}`).join(', '));
  }
  if (p.aiSummary) parts.push(`*Summary:* ${p.aiSummary}`);
  if (p.added && p.added.length) parts.push(`*Added (${p.addedCount}):*\n${quote(p.added)}`);
  if (p.removed && p.removed.length) parts.push(`*Removed (${p.removedCount}):*\n${quote(p.removed)}`);
  return { json: { text: parts.join('\n'), url: p.url, name: p.name || p.title || '' } };
});
